const TS={};
function table(id,o){const st=TS[id]||(TS[id]={q:'',sort:null,dir:1,pg:1,f:{},sel:new Set()});const size=o.size||8;
 let rows=o.rows.filter(r=>(!st.q||o.cols.some(c=>String(c.v(r)).toLowerCase().includes(st.q.toLowerCase())))&&Object.entries(st.f).every(([k,v])=>!v||String(o.filters.find(f=>f.k===k).v(r))===v));
 if(st.sort!=null){const c=o.cols[st.sort];rows=[...rows].sort((a,b)=>{const x=c.v(a),y=c.v(b);return(typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),'vi'))*st.dir})}
 const pages=Math.max(1,Math.ceil(rows.length/size));st.pg=Math.min(st.pg,pages);const vis=rows.slice((st.pg-1)*size,st.pg*size);o._rows=rows;TS[id].cur=rows;TS[id].cols=o.cols;TS[id].name=o.name||id;
 const allSel=vis.length&&vis.every(r=>st.sel.has(o.key(r)));
 return `<div class="card" style="overflow:hidden">${o.title?`<div class="cp" style="padding-bottom:0"><div class="ch" style="margin:0"><div><h2>${t(o.title)}</h2>${o.sub?`<p>${o.sub}</p>`:''}</div></div></div>`:''}
 <div class="tb"><label class="sr">${ic('search')}<input data-tq="${id}" placeholder="${t('Tìm…')}" value="${esc(st.q)}" aria-label="${t('Tìm…')}"></label>${(o.filters||[]).map(f=>`<select class="sel" data-tf="${id}|${f.k}" aria-label="${f.l}"><option value="">${f.l}: ${t('Tất cả')}</option>${[...new Set(o.rows.map(f.v))].map(v=>`<option ${st.f[f.k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`).join('')}<span style="flex:1"></span><button class="btn sm" data-a="csv" data-id="${id}">${ic('dl')}${t('Xuất CSV')}</button><button class="btn sm" data-a="pdf">${t('Xuất PDF')}</button></div>
 ${st.sel.size?`<div class="bulk">${t('Đã chọn')} ${st.sel.size}${(o.bulk||[]).map(b=>`<button class="btn sm ${b.c||''}" data-a="bulk" data-id="${id}" data-b="${b.k}">${b.l}</button>`).join('')}<button class="btn sm" data-a="clr" data-id="${id}">${t('Bỏ chọn')}</button></div>`:''}
 <div class="tw"><table><thead><tr>${o.bulk?`<th style="width:44px"><input type="checkbox" data-ta="${id}" ${allSel?'checked':''} aria-label="all"></th>`:''}${o.cols.map((c,i)=>`<th class="s ${c.n?'n':''}" data-ts="${id}|${i}">${t(c.l)}${st.sort===i?(st.dir>0?' ↑':' ↓'):''}</th>`).join('')}</tr></thead><tbody>${vis.map(r=>`<tr class="${o.open?'cl':''}" ${o.open?`data-o="${o.open}|${esc(o.key(r))}"`:''}>${o.bulk?`<td><input type="checkbox" data-tr="${id}|${esc(o.key(r))}" ${st.sel.has(o.key(r))?'checked':''} aria-label="select"></td>`:''}${o.cols.map(c=>`<td class="${c.n?'n':''}">${c.h?c.h(r):esc(c.v(r))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="9" style="text-align:center;color:var(--mut);padding:40px">${t('Không có dữ liệu')}</td></tr>`}</tbody></table></div>
 <div class="tf"><span>${t('Hiển thị')} ${rows.length?(st.pg-1)*size+1:0}–${Math.min(rows.length,st.pg*size)} ${t('trên')} ${rows.length}</span><div class="pg">${Array.from({length:pages},(_,i)=>`<button class="${i+1===st.pg?'on':''}" data-tp="${id}|${i+1}">${i+1}</button>`).join('')}</div></div></div>`}
const nmc=(ico,a,b)=>`<div class="nm"><span class="ico">${ic(ico)}</span><div><b>${esc(a)}</b><small>${esc(b)}</small></div></div>`;
// charts
function line(series,labels,h=220,fmt=v=>v.toLocaleString('vi-VN')){const W=760,pl=44,pb=26,pt=12,max=Math.max(...series.flatMap(s=>s.d))*1.1,n=labels.length,x=i=>pl+i*(W-pl-10)/(n-1),y=v=>pt+(h-pt-pb)*(1-v/max);
 return `<div class="chart"><svg viewBox="0 0 ${W} ${h}" role="img">${[0,.25,.5,.75,1].map(k=>`<line x1="${pl}" x2="${W-10}" y1="${y(max*k)}" y2="${y(max*k)}" stroke="var(--line)"/><text x="${pl-8}" y="${y(max*k)+4}" text-anchor="end">${k?(max*k>=1e6?(max*k/1e6).toFixed(1)+'tr':max*k>=1e3?Math.round(max*k/1e3)+'k':Math.round(max*k)):0}</text>`).join('')}
 ${series.map((s,si)=>{const p=s.d.map((v,i)=>`${i?'L':'M'}${x(i)} ${y(v)}`).join(' ');return `${si?'':`<path d="${p} L${x(n-1)} ${h-pb} L${x(0)} ${h-pb}Z" fill="${s.c}" opacity=".1"/>`}<path d="${p}" fill="none" stroke="${s.c}" stroke-width="${si?2:3}" ${si?'stroke-dasharray="6 5"':''} stroke-linecap="round" stroke-linejoin="round"/>`}).join('')}
 ${labels.map((l,i)=>`<text x="${x(i)}" y="${h-6}" text-anchor="middle">${l}</text>`).join('')}
 ${labels.map((l,i)=>{const tx=Math.min(Math.max(x(i)-70,pl),W-150);return `<g class="hv"><rect x="${x(i)-(W-pl)/n/2}" y="0" width="${(W-pl)/n}" height="${h-pb}"/><line x1="${x(i)}" x2="${x(i)}" y1="${pt}" y2="${h-pb}" stroke="var(--pri)" stroke-opacity=".35"/>${series.map(s=>`<circle cx="${x(i)}" cy="${y(s.d[i])}" r="5" fill="${s.c}" stroke="#fff" stroke-width="2"/>`).join('')}<g class="tp"><rect x="${tx}" y="4" width="140" height="${22+series.length*18}" rx="10"/><text x="${tx+10}" y="22">${l}</text>${series.map((s,k)=>`<text x="${tx+10}" y="${40+k*18}">${s.n}: ${fmt(s.d[i])}</text>`).join('')}</g></g>`}).join('')}</svg></div>`}
function donut(parts){const tot=parts.reduce((a,p)=>a+p.v,0);let a=0;const R=54,C=2*Math.PI*R;return `<div style="display:flex;gap:22px;align-items:center;flex-wrap:wrap"><svg width="150" height="150" viewBox="0 0 150 150"><g transform="rotate(-90 75 75)">${parts.map(p=>{const l=p.v/tot*C,s=`<circle cx="75" cy="75" r="${R}" fill="none" stroke="${p.c}" stroke-width="22" stroke-dasharray="${l} ${C-l}" stroke-dashoffset="${-a}"><title>${p.n}: ${p.v}</title></circle>`;a+=l;return s}).join('')}</g><text x="75" y="80" text-anchor="middle" style="font:700 20px -apple-system,BlinkMacSystemFont,'SF Pro Text','SF Pro Display',system-ui,'Segoe UI',sans-serif;fill:var(--ink)">${tot.toLocaleString('vi-VN')}</text></svg><div>${parts.map(p=>`<div style="display:flex;gap:8px;align-items:center;margin:6px 0"><i style="width:10px;height:10px;border-radius:3px;background:${p.c}"></i>${p.n} <b style="margin-left:auto;padding-left:14px">${p.v.toLocaleString('vi-VN')}</b></div>`).join('')}</div></div>`}
const gen=(n,base,amp,seed)=>Array.from({length:n},(_,i)=>Math.round(base+amp*(i/n)+amp*.35*Math.sin(i*1.7+seed)));

