const vw=n=>{const d=['không','một','hai','ba','bốn','năm','sáu','bảy','tám','chín'];const t3=(x,full)=>{const h=Math.floor(x/100),t=Math.floor(x%100/10),u=x%10;let s='';if(h||full)s+=d[h]+' trăm ';if(t>1){s+=d[t]+' mươi ';s+=u===1?'mốt ':u===5?'lăm ':u?d[u]+' ':''}else if(t===1){s+='mười ';s+=u===5?'lăm ':u?d[u]+' ':''}else if(u){if(h||full)s+='lẻ ';s+=d[u]+' '}return s};n=Math.round(n);if(!n)return 'Không đồng';const g=[];while(n>0){g.unshift(n%1000);n=Math.floor(n/1000)}const U=['',' nghìn',' triệu',' tỷ',' nghìn tỷ'];let s='';g.forEach((x,i)=>{if(x)s+=t3(x,i>0)+U[g.length-1-i].trim()+' '});s=s.trim().replace(/\s+/g,' ');return s.charAt(0).toUpperCase()+s.slice(1)+' đồng chẵn'};
