function cusDrawer(id){const c=CUS.find(x=>x.id===id),cts=CT.filter(x=>x.cus===id),cs=ads.filter(a=>a.brand===c.short||a.brand.includes(c.short.split(' ')[0]));return '<h2>'+esc(c.short)+'</h2><p class="sub">'+esc(c.name)+'</p><div style="margin:12px 0">'+tag(c.state==='Đang hợp tác'?'Đang hoạt động':c.state)+'</div><dl class="kv"><dt>Mã khách hàng</dt><dd class="mono">'+c.id+'</dd><dt>Mã số thuế</dt><dd class="mono">'+c.tax+'</dd><dt>Địa chỉ</dt><dd>'+esc(c.addr)+'</dd><dt>Người đại diện</dt><dd>'+esc(c.rep)+' · '+esc(c.title)+'</dd><dt>Điện thoại</dt><dd class="mono">'+c.phone+'</dd><dt>Email</dt><dd>'+c.email+'</dd><dt>Đầu mối</dt><dd>'+esc(c.contact)+'</dd><dt>Ngành</dt><dd>'+c.ind+'</dd><dt>Phụ trách</dt><dd>'+c.owner+'</dd><dt>Điều khoản</dt><dd>'+c.terms+'</dd><dt>Hạn mức công nợ</dt><dd class="mono">'+vnd(c.limit)+'</dd><dt>Công nợ hiện tại</dt><dd class="mono" style="color:'+(c.debt>c.limit*.8?'var(--bad)':'var(--ink)')+'">'+vnd(c.debt)+'</dd><dt>Hợp tác từ</dt><dd>'+c.since+'</dd></dl><h3 style="margin:0 0 8px;font-size:15px">Hợp đồng ('+cts.length+')</h3>'+(cts.map(x=>'<div class="mono" style="display:flex;justify-content:space-between;gap:10px;padding:10px 12px;background:var(--bg);border-radius:8px;margin-bottom:6px;font-size:12.5px"><span>'+x.id+' · '+x.state+'</span><b>'+vnd(x.val)+'</b></div>').join('')||'<p class="sub">Chưa có hợp đồng.</p>')+'<h3 style="margin:16px 0 8px;font-size:15px">Chiến dịch ('+cs.length+')</h3>'+(cs.map(a=>'<div style="display:flex;justify-content:space-between;padding:8px 0;border-top:1px solid var(--line)"><span>'+esc(a.name)+'</span>'+tag(a.state)+'</div>').join('')||'<p class="sub">Chưa có chiến dịch.</p>')+'<div class="acts" style="margin-top:20px"><button class="btn p" data-a="mk-contract" data-id="'+c.id+'">Tạo hợp đồng từ mẫu</button><button class="btn" data-a="dclose">Đóng</button></div>'}
function contractDoc(c,o){const A=businessA;const val=+o.val,months=+o.months,adv=+o.adv;const lines=[['Điều 1. Nội dung dịch vụ','Bên A cung cấp cho Bên B dịch vụ phát quảng cáo trên mạng lưới màn hình của Bên A gồm: Smart TV, màn hình thang máy (dọc 18,5"–23,8") và bảng LED P5 tại chung cư, bãi đỗ xe, theo kế hoạch phát tại Phụ lục 01 (loại màn hình, khu vực, khung giờ, tần suất, thời lượng).'],['Điều 2. Thời hạn','Hợp đồng có hiệu lực từ ngày '+o.from+' và kéo dài '+months+' tháng, trừ khi chấm dứt sớm theo Điều 9.'],['Điều 3. Giá trị và thanh toán','Tổng giá trị hợp đồng: '+vnd(val)+' (bằng chữ: '+vw(val)+'), chưa bao gồm thuế GTGT 8%. Bên B thanh toán trước '+adv+'% trong vòng 07 ngày kể từ ngày ký; phần còn lại thanh toán theo điều khoản: '+c.terms+', căn cứ biên bản nghiệm thu và hóa đơn điện tử hợp lệ. Thanh toán bằng chuyển khoản vào tài khoản của Bên A.'],['Điều 4. Nội dung quảng cáo','Bên B chịu trách nhiệm về tính hợp pháp, bản quyền và tính xác thực của nội dung. Bên B cung cấp tệp đúng định dạng và độ phân giải theo Phụ lục 01 ít nhất 05 ngày làm việc trước ngày phát. Bên A có quyền từ chối hoặc gỡ nội dung vi phạm pháp luật, thuần phong mỹ tục hoặc quy định của chủ tòa nhà.'],['Điều 5. Nghiệm thu và báo cáo','Bên A cung cấp báo cáo phát (proof-of-play) theo tuần và báo cáo tổng kết khi kết thúc. Số liệu từ hệ thống của Bên A là căn cứ nghiệm thu; Bên B có 05 ngày làm việc để phản hồi, quá hạn xem như chấp thuận.'],['Điều 6. Quyền và nghĩa vụ của Bên A','Phát đúng lịch đã thống nhất; thông báo kịp thời khi có sự cố thiết bị; phát bù hoặc hoàn tiền tương ứng nếu không phát đủ cam kết do lỗi của Bên A; bảo mật thông tin của Bên B.'],['Điều 7. Quyền và nghĩa vụ của Bên B','Cung cấp nội dung đúng hạn; thanh toán đầy đủ, đúng hạn; không tự ý can thiệp thiết bị; chịu trách nhiệm trước pháp luật về nội dung quảng cáo.'],['Điều 8. Bảo mật và dữ liệu cá nhân','Hai bên giữ bí mật thông tin của nhau. Việc xử lý dữ liệu cá nhân (nếu có) tuân thủ Nghị định 13/2023/NĐ-CP và quy định hiện hành.'],['Điều 9. Chấm dứt','Mỗi bên có quyền chấm dứt khi bên kia vi phạm nghiêm trọng và không khắc phục sau 15 ngày kể từ khi nhận thông báo bằng văn bản. Khi chấm dứt, hai bên đối soát và thanh toán phần đã thực hiện.'],['Điều 10. Bất khả kháng','Không bên nào chịu trách nhiệm đối với chậm trễ do bất khả kháng (thiên tai, dịch bệnh, mất điện diện rộng, quyết định của cơ quan nhà nước). Bên bị ảnh hưởng thông báo trong 05 ngày làm việc.'],['Điều 11. Giải quyết tranh chấp','Ưu tiên thương lượng; nếu không đạt được, đưa ra Tòa án có thẩm quyền tại nơi đặt trụ sở Bên A. Hợp đồng lập thành 02 bản, mỗi bên giữ 01 bản có giá trị như nhau.']];
return '<div class="paper"><div style="text-align:center"><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b><br><b>Độc lập – Tự do – Hạnh phúc</b><br>—————</div><h2 style="text-align:center;margin:18px 0 4px">HỢP ĐỒNG DỊCH VỤ QUẢNG CÁO</h2><p style="text-align:center;margin:0 0 16px">Số: '+o.no+'</p><p>Hôm nay, ngày '+o.from+', tại Hà Nội, chúng tôi gồm:</p><p><b>BÊN A (Bên cung cấp dịch vụ): '+A.name.toUpperCase()+'</b><br>Mã số thuế: '+A.tax+' · Địa chỉ: '+A.addr+'<br>Đại diện: '+A.rep+' · Chức vụ: Giám đốc · Email: '+A.email+'</p><p><b>BÊN B (Bên thuê quảng cáo): '+esc(c.name.toUpperCase())+'</b><br>Mã số thuế: '+c.tax+' · Địa chỉ: '+esc(c.addr)+'<br>Đại diện: '+esc(c.rep)+' · Chức vụ: '+esc(c.title)+' · Điện thoại: '+c.phone+'</p><p>Hai bên thống nhất ký kết hợp đồng với các điều khoản sau:</p>'+lines.map(l=>'<p><b>'+l[0]+'</b><br>'+l[1]+'</p>').join('')+'<p><b>Phụ lục 01.</b> Kế hoạch phát: loại màn hình (Smart TV / thang máy / LED P5), khu vực, khung giờ, tần suất, thời lượng, tệp creative và độ phân giải.</p><div style="display:grid;grid-template-columns:1fr 1fr;text-align:center;margin-top:28px;gap:20px"><div><b>ĐẠI DIỆN BÊN A</b><br><i>(Ký, ghi rõ họ tên, đóng dấu)</i><br><br><br><br>'+A.rep+'</div><div><b>ĐẠI DIỆN BÊN B</b><br><i>(Ký, ghi rõ họ tên, đóng dấu)</i><br><br><br><br>'+esc(c.rep)+'</div></div></div>'}
