function dlg(title,fields,ok){const d=document.createElement('dialog');d.className='dlg tvn'+(S.dark?' dark':'');d.innerHTML=`<form method="dialog"><h2 style="margin:0">${title}</h2>${fields.map(f=>`<div class="fd"><label>${f.l}</label>${f.o?`<select name="${f.n}">${f.o.map(o=>`<option>${o}</option>`).join('')}</select>`:`<input name="${f.n}" type="${f.t||'text'}" value="${f.v||''}" ${f.r===0?'':'required'}>`}</div>`).join('')}<div class="da"><button class="btn" type="button" data-x>${t('Hủy')}</button><button class="btn p">${t('Lưu')}</button></div></form>`;document.body.append(d);d.showModal();d.querySelector('[data-x]').onclick=()=>d.close();d.querySelector('form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));d.close();ok(v)};d.onclose=()=>d.remove()}
